// The plates the slice goldens are recorded with (test/goldens/slices.json): each a preset fixture and
// placed objects, as protocol v2 SliceParams. tools/goldens/record-slices-v1.mjs sliced them with the
// v0.1.0 release (its own host, protocol v1); the conformance suite slices them through the v2 host and
// requires the same G-code (the "; generated by" line aside, which holds the time).
import { readFileSync } from 'node:fs';
import type { Config } from '../../packages/protocol/src/data.ts';
import type { SliceParams } from '../../packages/protocol/src/ops.ts';
import { box, cube, cylinder } from '../fixtures.ts';
import { bandedCylinder, facetPaint, paintAll, segmentTriangles, tShape } from '../helpers/paint.ts';

interface PresetFixture {
  machine: Config;
  process: Config;
  filaments: Config[];
}

const fixture = (id: string): PresetFixture => {
  const { machine, process, filaments } = JSON.parse(readFileSync(new URL(`../fixtures/presets/${id}.json`, import.meta.url), 'utf8')) as PresetFixture;
  return { machine, process, filaments };
};

export interface Plate {
  id: string;
  params(): SliceParams;
}

const mesh = (positions: Float32Array) => ({ positions });

export const PLATES: readonly Plate[] = [
  {
    id: 'm1-cube',
    params: () => ({ configs: fixture('muon3d-m1-0.4'), objects: [{ name: 'Cube.stl', mesh: mesh(cube([100, 90])) }] }),
  },
  {
    id: 'm1-object-settings',
    params: () => ({
      configs: fixture('muon3d-m1-0.4'),
      objects: [
        { name: 'CubeA.stl', mesh: mesh(cube([60, 60])), config: { layer_height: '0.1', wall_loops: '5' } },
        { name: 'CubeB.stl', mesh: mesh(cube([130, 60])) },
      ],
    }),
  },
  {
    id: 'm1-two-cubes',
    params: () => ({
      configs: fixture('muon3d-m1-0.4'),
      objects: [
        { name: 'Cube.stl', mesh: mesh(cube([100, 90], 15)) },
        { name: 'Cube_2.stl', mesh: mesh(cube([140, 90], 15)) },
      ],
    }),
  },
  {
    id: 'm1-cylinder-arcs',
    params: () => {
      const configs = fixture('muon3d-m1-0.4');
      return { configs: { ...configs, process: { ...configs.process, enable_arc_fitting: '1' } }, objects: [{ name: 'Cylinder.stl', mesh: mesh(cylinder([100, 90], 15, 10)) }] };
    },
  },
  {
    id: 'x1c-box',
    params: () => ({ configs: fixture('bbl-x1c-0.4'), objects: [{ name: 'Box.stl', mesh: mesh(box([30, 20, 12], [128, 128])) }] }),
  },
];

/**
 * The painted plates (protocol 2.2, PlateObject.paint), whose goldens are `painted` in test/goldens/slices.json,
 * recorded by tools/goldens/record-slices-painted.mjs. Painted objects take the engine's painted path (the mesh
 * as sent, the codes through Orca's 3MF string reader). Fuzzy skin has no golden: Orca seeds its noise from
 * std::random_device (Feature/FuzzySkin/FuzzySkin.cpp), so its G-code differs on every run; test/paint.test.ts
 * checks it by shape instead.
 */
export const PAINTED_PLATES: readonly Plate[] = [
  {
    // Tree supports with automatic overhangs, both overhangs blocked: no support at all.
    id: 'm1-t-blockers-tree',
    params: () => {
      const t = tShape([100, 90]);
      return {
        configs: withProcess(fixture('muon3d-m1-0.4'), { enable_support: '1', support_type: 'tree(auto)' }),
        objects: [{ name: 'T.stl', mesh: mesh(t.positions), paint: { supports: paintAll([...t.faces.leftWing, ...t.faces.rightWing], '8') } }],
      };
    },
  },
  {
    // Grid supports, enforcers only: one overhang enforced whole, the other only on split pieces of one triangle.
    id: 'm1-t-enforcers-normal',
    params: () => {
      const t = tShape([100, 90]);
      const [first] = t.faces.rightWing;
      return {
        configs: withProcess(fixture('muon3d-m1-0.4'), { enable_support: '1', support_type: 'normal(manual)' }),
        objects: [{ name: 'T.stl', mesh: mesh(t.positions), paint: { supports: facetPaint([...t.faces.leftWing.map((i): [number, string] => [i, '4']), [first, '0004053']]) } }],
      };
    },
  },
  {
    // Tree supports, enforcers only, on half of each overhang (a triangle split once, one child enforced).
    id: 'm1-t-enforcers-tree',
    params: () => {
      const t = tShape([100, 90]);
      return {
        configs: withProcess(fixture('muon3d-m1-0.4'), { enable_support: '1', support_type: 'tree(manual)' }),
        objects: [{ name: 'T.stl', mesh: mesh(t.positions), paint: { supports: facetPaint([[t.faces.leftWing[0], '401'], [t.faces.rightWing[1], '045']]) } }],
      };
    },
  },
  {
    // An aligned seam: enforced on a strip at -X, blocked on a strip at +Y.
    id: 'm1-cylinder-seam',
    params: () => {
      const c = bandedCylinder([100, 90], 15, 10, 96);
      const strip = (from: number, to: number) => [...segmentTriangles(c, 'lower', 96, from, to), ...segmentTriangles(c, 'upper', 96, from, to)];
      return {
        configs: withProcess(fixture('muon3d-m1-0.4'), { seam_position: 'aligned' }),
        objects: [{ name: 'Cylinder.stl', mesh: mesh(c.positions), paint: { seam: facetPaint([...strip(176.25, 183.75).map((i): [number, string] => [i, '4']), ...strip(75, 105).map((i): [number, string] => [i, '8'])]) } }],
      };
    },
  },
];

/** A box standing on `z0` (box() stands on the bed). */
export function boxAt(size: [number, number, number], center: [number, number], z0: number): Float32Array {
  const b = box(size, center);
  for (let i = 2; i < b.length; i += 3) b[i] += z0;
  return b;
}

/**
 * The T of the neighbour plates: a 10 x 10 x 40 mm pillar with a 60 x 12 x 4 mm cap on top, centred on `center`; the cap's
 * arms are overhangs 40 mm up.
 */
export function capT(center: [number, number]): Float32Array {
  const pillar = boxAt([10, 10, 40], center, 0);
  const cap = boxAt([60, 12, 4], center, 40);
  const out = new Float32Array(pillar.length + cap.length);
  out.set(pillar);
  out.set(cap, pillar.length);
  return out;
}

/**
 * Plates with several objects whose supports never come near another object (2.3): their G-code must be what the engine
 * gave before the plate's other objects became support blockers (`neighbours` in test/goldens/slices.json, recorded by
 * tools/goldens/record-slices-neighbours.mjs with the v0.4.0 release).
 */
export const NEIGHBOUR_PLATES: readonly Plate[] = [
  {
    // Organic tree supports, the block out of the T's reach (organic_support_reach: about 57 mm here; it is 77 mm away in Y).
    id: 'm1-t-far-block-tree',
    params: () => ({
      configs: withProcess(fixture('muon3d-m1-0.4'), { enable_support: '1', support_type: 'tree(auto)' }),
      objects: [
        { name: 'Tee.stl', mesh: mesh(capT([130, 130])) },
        { name: 'Block.stl', mesh: mesh(box([14, 14, 20], [40, 40])) },
      ],
    }),
  },
  {
    // Grid supports, two Ts 30 mm apart: only organic tree supports avoid other objects.
    id: 'm1-two-t-normal',
    params: () => ({
      configs: withProcess(fixture('muon3d-m1-0.4'), { enable_support: '1', support_type: 'normal(auto)' }),
      objects: [
        { name: 'Tee.stl', mesh: mesh(capT([100, 70])) },
        { name: 'Tee_2.stl', mesh: mesh(capT([100, 112])) },
      ],
    }),
  },
  {
    // Tree supports in the "Tree Hybrid" style (not organic), a block 20 mm from the T.
    id: 'm1-t-block-tree-hybrid',
    params: () => ({
      configs: withProcess(fixture('muon3d-m1-0.4'), { enable_support: '1', support_type: 'tree(auto)', support_style: 'tree_hybrid' }),
      objects: [
        { name: 'Tee.stl', mesh: mesh(capT([100, 90])) },
        { name: 'Block.stl', mesh: mesh(box([10, 10, 10], [100, 60])) },
      ],
    }),
  },
];

function withProcess(configs: PresetFixture, overrides: Record<string, string>): PresetFixture {
  return { ...configs, process: { ...configs.process, ...overrides } };
}

/** The G-code as the goldens compare it: without the header line that holds the time it was made. */
export function comparable(gcode: Uint8Array): string {
  return new TextDecoder().decode(gcode).replace(/^; generated by .*$/m, '; generated by');
}
